package br.com.adminpool.repository;
import br.com.adminpool.model.PedidoProduto; import br.com.adminpool.model.ResponsavelPagamento; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import java.time.LocalDate; import java.util.List;
public interface PedidoProdutoRepository extends JpaRepository<PedidoProduto, Long> { List<PedidoProduto> findAllByOrderByDataPedidoDesc(); List<PedidoProduto> findByClienteIdOrderByDataPedidoDesc(Long clienteId); List<PedidoProduto> findByStatusOrderByDataPedidoDesc(String status); List<PedidoProduto> findByPiscinaResponsavelUsuarioLoginIgnoreCaseOrderByDataPedidoDesc(String login); List<PedidoProduto> findByCodigoPedidoOrderByIdAsc(Long codigoPedido); List<PedidoProduto> findByDataConclusaoBetweenAndPagadorOrderByDataConclusaoDesc(LocalDate inicio, LocalDate fim, ResponsavelPagamento pagador); @Query(value="select nextval('pedido_codigo_seq')",nativeQuery=true) Long proximoCodigoPedido(); }
